// Real Electron provider selection and nested messenger tabs; isolated data and synthetic settings.
const fs=require('node:fs'),path=require('node:path'),os=require('node:os'),assert=require('node:assert/strict'),{_electron}=require('playwright-core');
const root=path.resolve(__dirname,'..'),home=fs.mkdtempSync(path.join(os.tmpdir(),'office-settings-desktop-'));let app;
fs.mkdirSync(path.join(home,'data'));fs.writeFileSync(path.join(home,'data/settings.json'),JSON.stringify({provider:'local',localSource:'managed',aiConnections:{'local:local':{endpoint:'http://127.0.0.1:11434/v1',model:'narae1'}}}));
(async()=>{const checks=[],errors=[];try{
 app=await _electron.launch({executablePath:require('electron'),args:[root],env:{...process.env,NARAE_OFFICE_HOME:home},timeout:60000});const page=await app.firstWindow();page.on('pageerror',e=>errors.push(e.message));await page.waitForSelector('#settingsButton');const choose=async id=>{await page.locator('#'+id).click();await page.waitForFunction(id=>document.getElementById(id).getAttribute('aria-pressed')==='true'&&!document.getElementById(id).disabled,id);};
 assert.equal(await page.locator('header button').count(),1);await page.locator('#settingsButton').click();assert.equal(await page.locator('dialog[open]').count(),1);assert.equal(await page.locator('[data-settings-tab]').count(),3);await page.locator('#autoSave').uncheck();await page.locator('#generalSettingsForm').getByRole('button',{name:'일반 설정 저장'}).click();await page.waitForFunction(()=>document.getElementById('generalSettingsStatus').textContent==='저장했습니다.');assert.equal(JSON.parse(fs.readFileSync(path.join(home,'data/settings.json'),'utf8')).hwpAutoSave,false);checks.push('three-main-settings-tabs-and-general-setting-persists');
 await page.locator('#settingsAITab').click();await page.waitForSelector('#localAIDialog:visible');assert.equal(await page.locator('[data-ai-provider]').count(),4);assert.equal(await page.locator('.ai-provider-panel:visible').count(),1);assert.equal(await page.locator('.recommended-model').count(),1);assert(await page.locator('.model-card[data-model=narae3] .recommended-model').isVisible());assert.equal((await page.evaluate(()=>window.narae.call('state'))).settings.model,'narae1');await page.screenshot({path:path.join(home,'settings-models.png')});checks.push('Narae3-recommendation-preserves-selected-Narae1');
 await choose('gptAIButton');await page.locator('#connectionMode').selectOption('api');await page.waitForSelector('#apiFields:visible');await page.locator('#model').fill('synthetic-gpt-model');await page.locator('#settingsForm').getByRole('button',{name:'설정 저장',exact:true}).click();await page.waitForFunction(()=>document.getElementById('settingsStatus').textContent==='저장했습니다.');await choose('claudeAIButton');await page.locator('#connectionMode').selectOption('oauth');await page.waitForSelector('#oauthFields:visible');assert((await page.locator('#login').textContent()).includes('Claude'));await page.screenshot({path:path.join(home,'settings-claude.png')});await choose('localAIButton');assert.equal((await page.evaluate(()=>window.narae.call('state'))).settings.model,'narae1');await choose('otherAIButton');assert(await page.locator('#otherAIFields').isVisible());assert.equal(await page.locator('.ai-provider-panel:visible').count(),1);await page.screenshot({path:path.join(home,'settings-other.png')});await choose('gptAIButton');await page.locator('#connectionMode').selectOption('api');await page.waitForFunction(()=>document.getElementById('model').value==='synthetic-gpt-model');checks.push('four-provider-buttons-and-independent-configurations');
 await page.locator('#settingsMessengerTab').click();await page.locator('#telegramButton').click();await page.waitForSelector('#telegramDialog:visible');assert.equal(await page.locator('.messenger-panel:visible').count(),1);await page.locator('#remoteButton').click();await page.waitForSelector('#remoteDialog:visible');assert.equal(await page.locator('.messenger-panel:visible').count(),1);assert.equal(await page.locator('dialog[open]').count(),1);await page.screenshot({path:path.join(home,'settings-messenger.png')});await page.locator('#remoteButton').focus();await page.keyboard.press('ArrowLeft');assert.equal(await page.locator('#telegramButton').getAttribute('aria-selected'),'true');checks.push('messenger-has-Telegram-and-Kakao-subtabs');
 await page.locator('#settingsMessengerTab').focus();await page.keyboard.press('Home');assert.equal(await page.locator('#settingsGeneralTab').getAttribute('aria-selected'),'true');await page.keyboard.press('ArrowDown');assert.equal(await page.locator('#settingsAITab').getAttribute('aria-selected'),'true');await page.keyboard.press('Escape');assert.equal(await page.locator('dialog[open]').count(),0);checks.push('main-and-nested-keyboard-navigation');
 await page.locator('#welcomeModels').click();await page.waitForSelector('#localAIDialog:visible');await page.locator('#closeSettings').click();await page.locator('#agentTab').click();assert.equal(await page.locator('.agent-conversation select,.agent-conversation .agent-heading').count(),0);assert(await page.locator('.agent-sidebar #agentChannel').isVisible());assert(await page.locator('.agent-sidebar #agentModel').isVisible());await page.locator('#agentModelSettings').click();await page.waitForSelector('#aiSettingsPanel:visible');await page.locator('#closeSettings').click();await page.locator('#agentConnect').click();await page.waitForSelector('#remoteDialog:visible');assert.equal(await page.locator('#settingsMessengerTab').getAttribute('aria-selected'),'true');await page.locator('#closeSettings').click();checks.push('sidebar-and-welcome-shortcuts-open-nested-settings');
 await page.screenshot({path:path.join(home,'agent.png')});await page.setViewportSize({width:1000,height:720});assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth||document.documentElement.scrollHeight>innerHeight),false);await page.screenshot({path:path.join(home,'agent-compact.png')});await page.locator('#settingsButton').click();await page.locator('#settingsAITab').click();await choose('localAIButton');assert.equal(await page.evaluate(()=>document.getElementById('settingsDialog').scrollWidth>document.getElementById('settingsDialog').clientWidth),false);await page.screenshot({path:path.join(home,'settings-compact.png')});checks.push('minimum-window-layout-without-horizontal-overflow');assert.deepEqual(errors,[]);const result={passed:true,home,checks};fs.writeFileSync(path.join(home,'result.json'),JSON.stringify(result,null,2));console.log(JSON.stringify(result,null,2));
 }finally{await app?.close();}})().catch(e=>{console.error(e.stack);console.error('QA home: '+home);process.exitCode=1;});
